uint64_t RenderingContextDriverVulkan::get_driver_memory_by_object_type(uint32_t p_type) const
{
	uint64_t ret = 0;
	for (uint32_t i = 0; i < VK_TRACKED_SYSTEM_ALLOCATION_SCOPE_COUNT; i++) {
		ret += driver_memory_tracker[p_type][i].get();
	}

	return ret;
}

